/**
 * # Legacy routing receipts
 *
 * Both golden suites use the original implementation at
 * `1e93038cffd4d2ca92ffd7bc8edeeebce389890d`, not expectations generated by the policy compiler.
 * Both suites have been reproduced in a detached worktree at that exact immutable base.
 * The original suite and its committed snapshot were copied there, then run *without* updating it:
 *
 * ```sh
 * JITI_FS_CACHE=false npx vitest run tests/policy-compatibility.test.ts
 * ```
 *
 * The old implementation passes that snapshot unchanged. This is reproducible evidence, independent
 * of the original capture chronology. The extended suite was also run on that immutable base:
 *
 * ```sh
 * JITI_FS_CACHE=false npx vitest run tests/policy-compatibility-edges.test.ts -u
 * ```
 *
 * That old-base run wrote three snapshots, with all three tests passing. The resulting snapshot was
 * copied back unchanged; both compatibility suites then passed against the policy implementation
 * without snapshot updates. All observations, credentials and errors are synthetic.
 *
 * SHA-256:
 * - `policy-compatibility.test.ts.snap`: `2443a743de81c2170ea4ac1ed35133cfcb555520b4d30ca6588d45a12fa59a01`
 * - `policy-compatibility-edges.test.ts.snap`: `182e2d8c55c97a042d67ea373e51e4b03fb6e7a6fa781845060aef6c23800959`
 *
 * The independent, verbatim merge-base oracle in `tests/fixtures/legacy-oracle/` adds a fixed-seed 4,096-case
 * differential property over random snapshots, tracker marks, incumbents, request reasons and retry
 * outcomes. Git blob pins prove the reference source is unchanged; the oracle never delegates to
 * production selection/routing. No new generator dependency is required.
 *
 * The receipts include route/thinking, legacy parsed omissions, complete decision JSON/text, complete
 * status output, confirmation reads, tracker marks, admission/recheck hints and failures across all
 * legacy strategies. Edge cases include numeric hysteresis/roundoff, missing timing, exact/past resets,
 * stale-grace boundaries, family/provider overlap, all-blocked multi-window hints, overlapping exact
 * confirmations in both completion orders, partial output and cancellation. Do not update these against
 * a refactored selector to make a regression pass.
 *
 */
/** Golden receipts captured on the pre-calculus implementation, never derived from its compiler. */
import { type Api, fauxAssistantMessage, type Model } from "@earendil-works/pi-ai";
import type { ModelRouteRequest } from "@earendil-works/pi-coding-agent";
import { expect, it } from "vitest";
import { parseConfig } from "../src/config.ts";
import { ExhaustionTracker } from "../src/exhaustion.ts";
import { formatDecision, type RouteDecision, Router } from "../src/router.ts";
import { CachedUsage, Clock } from "./fixtures/router.ts";

it("preserves legacy routes, diagnostics, errors and admissions byte for byte", async () => {
	const results = [];
	for (const strategy of [undefined, "ordered", "balanced"]) {
		for (const state of ["measured", "fallback", "unlimited", "stale", "expired", "blocked"]) {
			for (const reason of ["user", "direct", "continuation", "retry"] as const) {
				const profile = parseConfig({
					profiles: {
						golden: {
							strategy,
							chain: [{ model: "a/sonnet", thinking: "high" }, { model: "b/terra" }, { model: "c/third" }],
						},
					},
				})[0];
				if (!profile) throw new Error("missing fixture");
				const clock = new Clock();
				const usage = new CachedUsage(clock);
				usage.set("a", state === "blocked" ? 100 : 70);
				usage.set("b", state === "blocked" ? 100 : 20);
				usage.set("c", state === "blocked" ? 100 : 30);
				for (const snapshot of usage.snapshots.values()) {
					if (state === "fallback") snapshot.status = "unavailable";
					if (state === "unlimited") snapshot.credits = { available: true, unlimited: true };
					if (state === "stale" || state === "expired") {
						snapshot.status = "stale";
						snapshot.retrievedAt -= state === "stale" ? 900_000 : 900_001;
					}
				}
				const model = (provider: string): Model<Api> =>
					({
						provider,
						id: provider === "a" ? "sonnet" : provider === "b" ? "terra" : "third",
						api: "test",
					}) as unknown as Model<Api>;
				const decisions: RouteDecision[] = [];
				const router = new Router(usage, new ExhaustionTracker(clock.now), clock.now, (decision) =>
					decisions.push(decision),
				);
				const reads: string[] = [];
				const env = {
					resolve: (entry: { provider: string }) => model(entry.provider),
					refresh: async (failed: Model<Api>) => {
						reads.push(failed.provider);
						return { block: false };
					},
				};
				const request: ModelRouteRequest = {
					model: model("router"),
					thinkingLevel: "low",
					reason,
					messages: [],
					previous: { model: model("b") },
					failed: {
						model: model("b"),
						message: fauxAssistantMessage([], { stopReason: "error", errorMessage: "429", timestamp: clock.now() }),
					},
				};
				let route: unknown;
				try {
					route = await router.route(profile, request, env);
				} catch (error) {
					route = (error as Error).message;
				}
				results.push({
					strategy,
					state,
					reason,
					profile,
					route,
					decisions,
					text: decisions.map(formatDecision),
					reads,
					admission: router.admit("router/golden", new Map([["golden", profile]]), env),
				});
			}
		}
	}
	expect(JSON.stringify(results, null, 2)).toMatchSnapshot();
});
